  ];

  var GAMES = [
    { name:"ulg3", desc:"game portal · s3 hosted", url:"https://s3.amazonaws.com/ulg3/index.html", cover:"https://images.unsplash.com/photo-1542751371-adc38448a05e?w=800&q=80" },
    { name:"0n38", desc:"game portal · s3 hosted", url:"https://s3.amazonaws.com/0n38/index.html", cover:"https://images.unsplash.com/photo-1550745165-9bc0b252726f?w=800&q=80" },
    { name:"gn-math", desc:"huge library · hundreds of games", url:"https://gn-math.dev", cover:"https://images.unsplash.com/photo-1493711662062-fa541adb3fc8?w=800&q=80" }
  ];

  function mk(tag, attrs, text){ var el = document.createElementNS(NS, tag); if(attrs) for(var k in attrs) el.setAttribute(k, attrs[k]); if(text != null) el.textContent = text; return el; }
  var groups = $("groups"), search = $("search"), count = $("count"), empty = $("empty"), toast = $("toast"), sheet = $("sheet"), sheetUrl = $("sheetUrl"), sheetX = $("sheetX");

  function say(m){ toast.textContent = m; toast.classList.add("show"); clearTimeout(say.t); say.t = setTimeout(function(){ toast.classList.remove("show"); }, 1400); }
  function flash(b){ b.textContent = "copied"; b.classList.add("ok"); clearTimeout(flash.t); flash.t = setTimeout(function(){ b.textContent = "copy"; b.classList.remove("ok"); }, 1100); }
  function manual(t){ sheetUrl.value = t; sheet.classList.add("show"); try{ sheetUrl.focus(); sheetUrl.select(); sheetUrl.setSelectionRange(0, t.length); }catch(e){} }
  function copy(t, b){ var ok = function(){ flash(b); say("copied"); }; try{ if(navigator.clipboard && navigator.clipboard.writeText){ navigator.clipboard.writeText(t).then(ok, function(){ manual(t); }); } else manual(t); }catch(e){ manual(t); } }
  if(sheetX) sheetX.addEventListener("click", function(){ sheet.classList.remove("show"); });

  DATA.forEach(function(g, i){
    var d = mk("details", {class:"group"}); d.open = true; d.style.setProperty("--g", i);
    var s = mk("summary", {class:"gs"});
    var gh = mk("div", {class:"gh"});
    gh.appendChild(mk("span", {class:"kao"}, g.e));
    gh.appendChild(mk("span", {class:"gn"}, g.n));
    gh.appendChild(mk("span", {class:"pill"}, String(g.l.length)));
    gh.appendChild(mk("span", {class:"chev"}, "\u25be"));
    s.appendChild(gh); d.appendChild(s);
    var b = mk("div", {class:"gb"});
    g.l.forEach(function(u){
      var li = mk("div", {class:"li"});
      var span = mk("span", {class:"u"});
      var stripped = u.replace(/^https?:\/\//, "");
      var host = stripped.split("/")[0];
      span.innerHTML = "https://<b>" + host + "</b>" + stripped.slice(host.length);
      li.appendChild(span);
      var acts = mk("div", {class:"acts"});
      var cb = mk("button", {type:"button", class:"btn"}, "copy");
      cb.addEventListener("click", function(ev){ ev.preventDefault(); ev.stopPropagation(); copy(u, cb); });
      acts.appendChild(cb);
      var oa = mk("a", {class:"btn", href:u, target:"_blank", rel:"noopener noreferrer"}, "open");
      acts.appendChild(oa);
      li.appendChild(acts);
      b.appendChild(li);
    });
    d.appendChild(b);
    groups.appendChild(d);
  });

  var grid = $("gameGrid");
  GAMES.forEach(function(g){
    var card = mk("div", {class:"gameCard"});
    var cover = mk("div", {class:"cover"}); cover.style.backgroundImage = "url('" + g.cover + "')";
    card.appendChild(cover);
    var info = mk("div", {class:"info"});
    info.appendChild(mk("div", {class:"name"}, g.name));
    info.appendChild(mk("div", {class:"desc"}, g.desc));
    var acts = mk("div", {class:"acts"});
    var oa = mk("a", {class:"btn", href:g.url, target:"_blank", rel:"noopener noreferrer"}, "open");
    acts.appendChild(oa);
    info.appendChild(acts);
    card.appendChild(info);
    grid.appendChild(card);
  });

  function update(){
    var q = (search.value || "").trim().toLowerCase(); var gc = 0, lc = 0;
    var all = groups.querySelectorAll(".group");
    for(var i = 0; i < all.length; i++){
      var grp = all[i];
      var gnEl = grp.querySelector(".gn");
      var hitName = !q || (gnEl && gnEl.textContent.toLowerCase().indexOf(q) > -1);
      var items = grp.querySelectorAll(".li"); var n = 0;
      for(var j = 0; j < items.length; j++){
        var it = items[j]; var uEl = it.querySelector(".u");
        var hit = hitName || (uEl && uEl.textContent.toLowerCase().indexOf(q) > -1);
        it.classList.toggle("hidden", !hit); if(hit) n++;
      }
      var pill = grp.querySelector(".pill"); if(pill) pill.textContent = n;
      grp.classList.toggle("hidden", !n);
      if(q && n) grp.open = true;
      if(n){ gc++; lc += n; }
    }
    count.innerHTML = "<b>" + gc + "</b> groups, <b>" + lc + "</b> links";
    empty.classList.toggle("show", !gc);
  }
  search.addEventListener("input", update);
  document.addEventListener("keydown", function(e){
    if(e.key === "/" && document.activeElement !== search){ e.preventDefault(); search.focus(); search.select(); }
    else if(e.key === "Escape"){ if(sheet) sheet.classList.remove("show"); if(search.value){ search.value = ""; update(); } }
  });

  var tabLinks = $("tabLinks"), tabGames = $("tabGames"), panelLinks = $("panelLinks"), panelGames = $("panelGames");
  tabLinks.addEventListener("click", function(){ tabLinks.classList.add("active"); tabGames.classList.remove("active"); panelLinks.classList.add("on"); panelGames.classList.remove("on"); });
  tabGames.addEventListener("click", function(){ tabGames.classList.add("active"); tabLinks.classList.remove("active"); panelGames.classList.add("on"); panelLinks.classList.remove("on"); });

  update();
})();
